import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.C1aUlgNS.js";const u=JSON.parse('{"title":"Quick start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md"}'),d={name:"guide/quick-start.md"};function n(i,e,r,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p>Every feature of Jevwright can be tried in a few minutes on the <strong>Demo App</strong>, a small online shop we host for you. This page shows how, and then what your own app needs.</p><h2 id="the-demo-app" tabindex="-1">The Demo App <a class="header-anchor" href="#the-demo-app" aria-label="Permalink to &quot;The Demo App&quot;">​</a></h2><p>The Demo App is a copy of the Swag Labs shop at <strong><a href="https://demo.94.72.126.118.sslip.io" target="_blank" rel="noreferrer">https://demo.94.72.126.118.sslip.io</a></strong>. You sign in, add products to the cart and check out. Its sign-in page lists the test users; all of them use the password <code>secret_sauce</code>:</p><table tabindex="0"><thead><tr><th>User</th><th>How the shop treats them</th></tr></thead><tbody><tr><td><code>standard_user</code></td><td>Everything works</td></tr><tr><td><code>locked_out_user</code></td><td>Cannot sign in; the shop shows an error</td></tr><tr><td><code>problem_user</code>, <code>performance_glitch_user</code>, <code>error_user</code>, <code>visual_user</code></td><td>Broken images, slow pages, errors or a shifted layout, to see how tests react</td></tr></tbody></table><p>The shop keeps the signed-in user in a cookie named <code>session-username</code>, so a test can start already signed in by setting that cookie (see <code>buy-a-backpack.yaml</code> below).</p><h2 id="_1-register" tabindex="-1">1. Register <a class="header-anchor" href="#_1-register" aria-label="Permalink to &quot;1. Register&quot;">​</a></h2><p>Open the <a href="https://app.94.72.126.118.sslip.io" target="_blank" rel="noreferrer">web workspace</a> and register with an email and a password. Your account starts with a <strong>Quick Start</strong> project in the sidebar. Its Variables are already set:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Value</th></tr></thead><tbody><tr><td><code>BASE</code></td><td><code>https://demo.94.72.126.118.sslip.io</code>, the Demo App</td></tr><tr><td><code>SWAG_PASSWORD</code></td><td><code>secret_sauce</code></td></tr></tbody></table><p>Every Quick Start file starts with <code>baseUrl: &quot;{{BASE}}&quot;</code>, so it tests the Demo App. If you delete the project, <strong>Add the Quick Start project</strong> under the sidebar&#39;s tree brings it back.</p><h2 id="_2-pick-a-file" tabindex="-1">2. Pick a file <a class="header-anchor" href="#_2-pick-a-file" aria-label="Permalink to &quot;2. Pick a file&quot;">​</a></h2><p>Each file opens with three comment lines: what it does, what to expect, and something to try.</p><table tabindex="0"><thead><tr><th>Feature</th><th>Folder</th><th>File</th></tr></thead><tbody><tr><td>Steps with selectors only; Jev is never called</td><td>1 Passing tests</td><td><code>sign-in-and-see-products.yaml</code></td></tr><tr><td>Skipping the sign-in page with a cookie</td><td>1 Passing tests</td><td><code>buy-a-backpack.yaml</code></td></tr><tr><td>A test that passes because the shop refuses the user</td><td>1 Passing tests</td><td><code>locked-out-user-sees-an-error.yaml</code></td></tr><tr><td>A failed check, with the step&#39;s reason and screenshot</td><td>2 Failing tests - see why they fail</td><td><code>wrong-total-fails-at-the-total.yaml</code></td></tr><tr><td>A selector that matches nothing</td><td>2 Failing tests - see why they fail</td><td><code>missing-button-fails.yaml</code></td></tr><tr><td>An alert the step does not expect</td><td>2 Failing tests - see why they fail</td><td><code>unexpected-alert-fails.yaml</code></td></tr><tr><td>Every problem of a file listed at once</td><td>3 Invalid files - fix the errors</td><td><code>seven-errors-at-once.yaml</code></td></tr><tr><td>A YAML syntax error</td><td>3 Invalid files - fix the errors</td><td><code>yaml-syntax-error.yaml</code></td></tr><tr><td>Jev finding one element on the screenshot, one in the page, and judging a <code>statement</code></td><td>4 Jev - find and check by description</td><td><code>find-and-check-with-jev.yaml</code></td></tr><tr><td>Jev finding elements from descriptions only</td><td>4 Jev - find and check by description</td><td><code>find-elements-by-description.yaml</code></td></tr><tr><td>Jev saving a step whose selector is out of date</td><td>4 Jev - find and check by description</td><td><code>fall-back-from-a-stale-selector.yaml</code></td></tr><tr><td>Jev judging a true <code>statement</code></td><td>4 Jev - find and check by description</td><td><code>judge-a-true-statement.yaml</code></td></tr><tr><td>Jev judging a false <code>statement</code></td><td>4 Jev - find and check by description</td><td><code>judge-a-false-statement.yaml</code></td></tr></tbody></table><h2 id="_3-run-a-passing-test" tabindex="-1">3. Run a passing test <a class="header-anchor" href="#_3-run-a-passing-test" aria-label="Permalink to &quot;3. Run a passing test&quot;">​</a></h2><p>Open <code>sign-in-and-see-products.yaml</code> and click <strong>Run</strong> (or press <code>Ctrl+Enter</code>). The <strong>Output console</strong> on the right follows the Run live, step by step. A passing Run ends like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Passed  6/6 passed</span></span>
<span class="line"><span>Step 1  open     line 8   Passed</span></span>
<span class="line"><span>Step 2  input    line 10  Passed</span></span>
<span class="line"><span>Step 3  input    line 13  Passed</span></span>
<span class="line"><span>Step 4  click    line 16  Passed</span></span>
<span class="line"><span>Step 5  waitFor  line 18  Passed</span></span>
<span class="line"><span>Step 6  assert   line 20  Passed</span></span></code></pre></div><p>Click <strong>Open run details</strong> to see the report: every step with its duration, how its element was found (<code>selector</code> here), and a screenshot of the page after it.</p><h2 id="_4-run-a-failing-test" tabindex="-1">4. Run a failing test <a class="header-anchor" href="#_4-run-a-failing-test" aria-label="Permalink to &quot;4. Run a failing test&quot;">​</a></h2><p>Open <code>wrong-total-fails-at-the-total.yaml</code> and run it. It expects a total of <code>$99.99</code>, but the shop charges <code>$32.39</code>, so step 10 fails, and steps 11 and 12 stay <strong>Pending</strong>, because a Run stops at the first failed step. The failed step shows its reason and a screenshot of the page at that moment:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Text of &quot;[data-test=&quot;total-label&quot;]&quot; did not contain &quot;Total: $99.99&quot; within 3000ms; it was &quot;Total: $32.39&quot;</span></span></code></pre></div><p>Do what the file&#39;s <code># Try:</code> line says, fix the total, and run it again.</p><h2 id="_5-let-jev-find-and-judge" tabindex="-1">5. Let Jev find and judge <a class="header-anchor" href="#_5-let-jev-find-and-judge" aria-label="Permalink to &quot;5. Let Jev find and judge&quot;">​</a></h2><p>Open the files in <strong>4 Jev - find and check by description</strong>:</p><ul><li><code>find-and-check-with-jev.yaml</code> shows all three ways Jev helps. Jev finds the backpack&#39;s Add to cart button on the screenshot (<code>visual</code>). The red T-shirt&#39;s View details button is its picture, with no label you can see, so Jev finds it by its name in the page instead (<code>dom</code>). The last step is a <code>statement</code> alone, which Jev judges from a screenshot. The other steps are plain selectors and checks.</li><li><code>find-elements-by-description.yaml</code> has no selectors for its buttons, only a <code>target</code> such as <code>&quot;&#39;Add to cart&#39; button of the Sauce Labs Backpack&quot;</code>. The report shows <code>visual</code> or <code>dom</code> for those steps: Jev found them.</li><li><code>fall-back-from-a-stale-selector.yaml</code> has a selector that no longer matches. The step also has a <code>target</code>, so Jev finds the button and the step passes; the report shows how.</li><li><code>judge-a-true-statement.yaml</code> and <code>judge-a-false-statement.yaml</code> check the page with a <code>statement</code> in plain words, which Jev judges from a screenshot. The false one fails with a reason that starts with <code>Statement does not hold</code>.</li></ul><h2 id="_6-fix-an-invalid-file" tabindex="-1">6. Fix an invalid file <a class="header-anchor" href="#_6-fix-an-invalid-file" aria-label="Permalink to &quot;6. Fix an invalid file&quot;">​</a></h2><p>Open <code>seven-errors-at-once.yaml</code>. The <strong>Debug console</strong> lists every problem with its line and its code, such as <code>Line 9: Unknown action &quot;aiAct&quot;</code> with <code>E005</code>, and the editor underlines each line. Click a problem to jump to its line. A file with problems cannot run. Fix them one by one; the list updates as you type and when you save. The <a href="./../reference/diagnostics.html">Diagnostics</a> page explains every code.</p><h2 id="test-your-own-app" tabindex="-1">Test your own app <a class="header-anchor" href="#test-your-own-app" aria-label="Permalink to &quot;Test your own app&quot;">​</a></h2><p>When you are ready to test your own app, check two things first.</p><div class="warning custom-block"><p class="custom-block-title">Your app must be public</p><p>Runs happen on our server, which reaches <strong>public</strong> web addresses only. <code>localhost</code>, private IP addresses such as <code>192.168.1.20</code> or <code>10.0.0.5</code>, an intranet, or a host you reach only over a VPN fail, usually with <code>net::ERR_FAILED</code> or <code>net::ERR_CONNECTION_REFUSED</code> on the <code>open</code> step. Deploy the app, or a preview of it, to a public domain such as <code>https://staging.example.com</code>.</p></div><div class="warning custom-block"><p class="custom-block-title">A sign-in needs a session the test can set</p><p>A test cannot solve a CAPTCHA, a code sent by email or text (2FA), or bot protection. Either sign in with a test user whose sign-in has none of these, or start the test already signed in: put a session cookie, a token header, or a storage entry in the file with <a href="./../reference/test-file.html#headers-cookies-and-storage"><code>cookies</code>, <code>headers</code>, <code>localStorage</code> or <code>sessionStorage</code></a>, and keep the token itself in a Project Variable.</p></div><p>Then create a Project for your app, set its <code>BASE</code> Variable to your app&#39;s URL, and follow the <a href="./workflow.html">General workflow</a>.</p>`,31)])])}const g=t(d,[["render",n]]);export{u as __pageData,g as default};
